From b98e0617d6bb0048a05ba19241bf685462d37cbd Mon Sep 17 00:00:00 2001
From: Kacper Paczos <kacperpaczos2024@proton.me>
Date: Mon, 31 Aug 2026 12:46:47 +0200
Subject: [PATCH] [Microphone Indicator] Tell recording the audio output apart
 from using the microphone

A recording stream attached to the monitor of a sink captures what the
speakers play, not what a microphone hears. Both cases produced the same
label so far: "<app> is using the microphone", next to a microphone icon,
even when no capture device was touched at all.

PulseAudioQt drops monitor sources from SourceModel (source_cb() in
context.cpp returns early for them), so a stream recording a monitor never
matches an entry there. Sinks do know their monitor's index, so the two
cases can be told apart by looking at SinkModel.

When nothing records an actual capture device, the item now shows
media-record-symbolic and says "<app> is recording the audio output
(<device>)". Streams on real capture devices are untouched. The item still
appears in both cases, so nothing that used to be signalled stops being
signalled - only the wording and the icon change for the monitor case.

BUG: 498362
CCBUG: 410637
---
 src/qml/microphoneindicator.cpp | 85 +++++++++++++++++++++++++++++++--
 src/qml/microphoneindicator.h   |  9 ++++
 2 files changed, 91 insertions(+), 3 deletions(-)

diff --git a/src/qml/microphoneindicator.cpp b/src/qml/microphoneindicator.cpp
index 4cfb996e..7b0ef4df 100644
--- a/src/qml/microphoneindicator.cpp
+++ b/src/qml/microphoneindicator.cpp
@@ -21,6 +21,7 @@
 #include <PulseAudioQt/Context>
 #include <PulseAudioQt/Models>
 #include <PulseAudioQt/Server>
+#include <PulseAudioQt/Sink>
 #include <PulseAudioQt/Source>

 using namespace PulseAudioQt;
@@ -33,6 +34,7 @@ MicrophoneIndicator::MicrophoneIndicator(QObject *parent)
     : QObject(parent)
     , m_sourceModel(new SourceModel(this))
     , m_sourceOutputModel(new SourceOutputModel(this))
+    , m_sinkModel(new SinkModel(this))
     , m_osdDBusInterface(new OsdServiceInterface(OSD_DBUS_SERVICE, OSD_DBUS_PATH, QDBusConnection::sessionBus(), this))
     , m_updateTimer(new QTimer(this))
 {
@@ -44,6 +46,9 @@ MicrophoneIndicator::MicrophoneIndicator(QObject *parent)
     connect(m_sourceOutputModel, &QAbstractItemModel::rowsRemoved, this, &MicrophoneIndicator::scheduleUpdate);
     connect(m_sourceOutputModel, &QAbstractItemModel::dataChanged, this, &MicrophoneIndicator::scheduleUpdate);

+    connect(m_sinkModel, &QAbstractItemModel::rowsInserted, this, &MicrophoneIndicator::scheduleUpdate);
+    connect(m_sinkModel, &QAbstractItemModel::rowsRemoved, this, &MicrophoneIndicator::scheduleUpdate);
+
     m_updateTimer->setInterval(0);
     m_updateTimer->setSingleShot(true);
     connect(m_updateTimer, &QTimer::timeout, this, &MicrophoneIndicator::update);
@@ -138,10 +143,27 @@ void MicrophoneIndicator::update()
         m_sni->setStandardActionsEnabled(false);
     }

+    // A stream attached to the monitor of a sink records what the speakers play,
+    // not what a microphone hears. PulseAudioQt keeps monitors out of SourceModel,
+    // so the only way to tell the two apart is to look at the sinks.
+    QList<QModelIndex> microphoneApps;
+    QList<QModelIndex> monitoringApps;
+    for (const QModelIndex &idx : apps) {
+        if (monitoredSink(idx)) {
+            monitoringApps.append(idx);
+        } else {
+            microphoneApps.append(idx);
+        }
+    }
+    const bool microphoneInUse = !microphoneApps.isEmpty();
+
     const bool allMuted = muted();

     QString iconName;
-    if (allMuted) {
+    if (!microphoneInUse) {
+        // Nothing is listening to a microphone, the audio output is being recorded
+        iconName = QStringLiteral("media-record-symbolic");
+    } else if (allMuted) {
         iconName = QStringLiteral("microphone-sensitivity-muted");
     } else {
         if (Source *defaultSource = m_preferredDevice.source()) {
@@ -160,13 +182,19 @@ void MicrophoneIndicator::update()
         }
     }

-    if (QGuiApplication::layoutDirection() == Qt::RightToLeft) {
+    if (microphoneInUse && QGuiApplication::layoutDirection() == Qt::RightToLeft) {
         iconName.append(QStringLiteral("-rtl"));
     }

     m_sni->setTitle(i18n("Microphone"));
     m_sni->setIconByName(iconName);
-    m_sni->setToolTip(QIcon::fromTheme(iconName), allMuted ? i18n("Microphone Muted") : i18n("Microphone"), toolTipForApps(apps));
+    if (microphoneInUse) {
+        m_sni->setToolTip(QIcon::fromTheme(iconName), allMuted ? i18n("Microphone Muted") : i18n("Microphone"), toolTipForApps(microphoneApps));
+    } else {
+        m_sni->setToolTip(QIcon::fromTheme(iconName),
+                          i18nc("@info:tooltip the audio output is being recorded, the microphone is not in use", "Audio Output Recorded"),
+                          toolTipForMonitoringApps(monitoringApps));
+    }

     if (m_muteAction) {
         m_muteAction->setChecked(allMuted);
@@ -300,6 +328,57 @@ QList<QModelIndex> MicrophoneIndicator::recordingApplications() const
     return indices;
 }

+PulseAudioQt::Sink *MicrophoneIndicator::monitoredSink(const QModelIndex &idx) const
+{
+    static const int s_deviceIndexRole = m_sourceOutputModel->role(QByteArrayLiteral("DeviceIndex"));
+    Q_ASSERT(s_deviceIndexRole > -1);
+    static const int s_sinkPulseObjectRole = m_sinkModel->role(QByteArrayLiteral("PulseObject"));
+    Q_ASSERT(s_sinkPulseObjectRole > -1);
+
+    const quint32 deviceIndex = idx.data(s_deviceIndexRole).toUInt();
+
+    for (int i = 0; i < m_sinkModel->rowCount(); ++i) {
+        auto *sink = qobject_cast<Sink *>(m_sinkModel->index(i, 0).data(s_sinkPulseObjectRole).value<QObject *>());
+        if (sink && sink->monitorIndex() == deviceIndex) {
+            return sink;
+        }
+    }
+
+    return nullptr;
+}
+
+QString MicrophoneIndicator::toolTipForMonitoringApps(const QList<QModelIndex> &apps) const
+{
+    Q_ASSERT(!apps.isEmpty());
+
+    if (apps.count() > 1) {
+        QStringList names;
+        names.reserve(apps.count());
+        for (const QModelIndex &idx : apps) {
+            names.append(sourceOutputDisplayName(idx));
+        }
+        names.removeDuplicates();
+        // Still more than one app?
+        if (names.count() > 1) {
+            return i18nc("List of apps is recording what the speakers play",
+                         "%1 are recording the audio output",
+                         names.join(i18nc("list separator for names of audio outputs", ", ")));
+        }
+    }
+
+    const QModelIndex appIdx = apps.constFirst();
+
+    // Name the device whose output is being recorded, there can be several.
+    if (Sink *sink = monitoredSink(appIdx)) {
+        return i18nc("App %1 is recording the output of device %2",
+                     "%1 is recording the audio output (%2)",
+                     sourceOutputDisplayName(appIdx),
+                     sink->description());
+    }
+
+    return i18nc("App is recording what the speakers play", "%1 is recording the audio output", sourceOutputDisplayName(appIdx));
+}
+
 QString MicrophoneIndicator::toolTipForApps(const QList<QModelIndex> &apps) const
 {
     Q_ASSERT(!apps.isEmpty());
diff --git a/src/qml/microphoneindicator.h b/src/qml/microphoneindicator.h
index b339b449..80b1c32e 100644
--- a/src/qml/microphoneindicator.h
+++ b/src/qml/microphoneindicator.h
@@ -25,6 +25,8 @@ class KStatusNotifierItem;

 namespace PulseAudioQt
 {
+class Sink;
+class SinkModel;
 class Source;
 class SourceModel;
 class SourceOutputModel;
@@ -60,12 +62,19 @@ private:
     void showOsd();

     QList<QModelIndex> recordingApplications() const;
+    /**
+     * The sink whose monitor the given recording stream is attached to,
+     * or nullptr when the stream records an actual capture device.
+     */
+    PulseAudioQt::Sink *monitoredSink(const QModelIndex &idx) const;
     QString toolTipForApps(const QList<QModelIndex> &apps) const;
+    QString toolTipForMonitoringApps(const QList<QModelIndex> &apps) const;
     QString sourceOutputDisplayName(const QModelIndex &idx) const;

     PreferredDevice m_preferredDevice;
     PulseAudioQt::SourceModel *const m_sourceModel = nullptr; // microphone devices
     PulseAudioQt::SourceOutputModel *const m_sourceOutputModel = nullptr; // recording streams
+    PulseAudioQt::SinkModel *const m_sinkModel = nullptr; // playback devices, to tell their monitors apart from microphones

     KStatusNotifierItem *m_sni = nullptr;
     QPointer<QAction> m_muteAction;
-- 
